dosya.icerik:
-- stok hareketlerini yukler (parca parca islenir). Parametre: gun
\set dosya '/data/gelen/stok_' :gun '.csv'
\set yukle '\\copy stok_gecici from ' :'dosya' ' with (format csv, header true)'
:yukle
insert into stok_hareket (id, gun, adet) select id, :'gun', adet from stok_gecici;
insert into yukleme_log (dosya, satir) select 'stok_' || :'gun' || '.csv', count(*) from stok_gecici_x;
truncate stok_gecici;
